  // La règle de la maquette qui tire d'un thème de Hestia les champs d'un thème du catalogue.
  const hex = (h) => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
  const toHex = (c) => `#${c.map((x) => Math.round(Math.max(0, Math.min(255, x))).toString(16).padStart(2, '0')).join('')}`;
  const mix = (a, b, k) => { const x = hex(a), y = hex(b); return toHex(x.map((v, i) => v * (1 - k) + y[i] * k)); };
  const rgba = (h, a) => { const [r, g, b] = hex(h); return `rgba(${r},${g},${b},${a})`; };
  const lum = (h) => { const [r, g, b] = hex(h).map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
  const contrast = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
  const decorUri = (d) => (d ? `url("data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 170' preserveAspectRatio='xMidYMax slice'>${d}</svg>`)}")` : 'none');
  // Les thèmes d'Odin et des événements, transformés en thèmes complets (cartes, textes, graphiques, tuiles) : la règle
  // de la maquette (fromOdin), recopiée telle quelle. Un thème sans ciel (Valhalla) n'y passe pas.
  function fromOdin(t, grp) {
    const dark = !!t.dark, p = t.panel, ink = t.ink;
    let a = t.accent; if (contrast('#ffffff', a) < 2.6) a = mix(a, '#000000', .3);
    return { name: t.name, grp, dark, sc: dark ? p : '#ffffff', gt: dark ? 22 : 40, blur0: 20, sheen: dark ? .1 : .45, mascot: t.mascot, bg: `${decorUri(t.decor)} center bottom/100% 40% no-repeat,linear-gradient(180deg,${t.sky[0]},${t.sky[1]})`, blob1: t.accent, blob2: t.mascot, blobO: dark ? .18 : .3,
      surface: dark ? `linear-gradient(140deg,${rgba(p, .8)},${rgba(p, .58)})` : 'linear-gradient(140deg,rgba(255,255,255,.74),rgba(255,255,255,.44))', solid: dark ? p : mix('#ffffff', t.sky[0], .12), border: dark ? 'rgba(255,255,255,.1)' : 'rgba(255,255,255,.85)', blur: 20, sat: 1.4,
      shadow: dark ? '0 14px 34px rgba(0,0,0,.3)' : `0 10px 28px ${rgba(ink, .1)},inset 0 1px 0 rgba(255,255,255,.9)`, ink, muted: mix(ink, dark ? p : '#ffffff', .38), accent: a,
      onA: `linear-gradient(135deg,${mix(a, '#ffffff', .12)},${mix(a, '#000000', .14)})`, onB: `linear-gradient(135deg,${t.mascot},${mix(t.mascot, '#000000', .22)})`, pal: [a, t.mascot, '#a35bff', '#16c1e6', '#2fcf92'],
      side: dark ? rgba(p, .7) : 'rgba(255,255,255,.5)', chip: dark ? 'rgba(255,255,255,.07)' : 'rgba(255,255,255,.6)', sel: dark ? 'rgba(255,255,255,.13)' : 'rgba(255,255,255,.92)', track: dark ? 'rgba(255,255,255,.12)' : rgba(ink, .1), line: dark ? 'rgba(255,255,255,.07)' : rgba(ink, .08), radius: 22,
      good: dark ? '#6CCFB8' : '#1D7F68', warn: dark ? '#F0B860' : '#8F6200', bad: dark ? '#EE8A70' : '#B23F2A' };
  }
  /** Une couleur CSS en [couleur #rrggbb, opacité]. */
  const couleur = (c) => { const m = String(c).match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/); if (m) return [toHex([+m[1], +m[2], +m[3]]), m[4] === undefined ? 1 : +m[4]]; return /^#/.test(c) ? [c.slice(0, 7), 1] : ['#202020', 1]; };
  // Le verre des cartes : la règle de la maquette (surfaceOf), recopiée telle quelle. `g` : la transparence, de 0
  // (plein) à 100 (vitre) ; la carte va d'une opacité a = 0,92 − 0,9 × g/100 à a × 0,45, son flou baisse avec g
